function collectReward(uint256 amount) external nonReentrant {
    require(amount > 0, "Amount must be greater than 0");
    _updatePool();                                            // forces re-anchor (LOCAL-001)
    rewardToken.safeTransferFrom(msg.sender, address(this), amount);
    rewardBalance += amount;
    rewardPerSecond = (rewardBalance * PRECISION) / depletionDuration;  // re-anchor again
}

function emergencyTransfer(address recipient) external onlyOwner {
    ... safeTransfer(recipient, phUSDBalance) ... safeTransfer(recipient, rewardTokenBalance) ...
    _pause();   // L226 unconditional; with pauser==0, unpause() can never succeed and balances are gone
}
